package model;

import jakarta.persistence.*;

/**
 * Represents a movie shown at the cinema.
 * <p>
 * This is a JPA entity mapped to the {@code movies} table. Its identifier is
 * generated automatically by the database.
 *
 * @author Matias Rosas
 * @author Camila Larsen
 * @author Matias Nerli
 * @version 1.0
 */
@Entity
@Table(name = "movies")
public class Movie {

    /**
     * Unique identifier, generated by the database.
     */
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /**
     * The movie title.
     */
    private String title;

    /**
     * The movie genre.
     */
    private String genre;

    /**
     * The age rating (ATP, +13, +16, +18).
     */
    private String filmRating;

    /**
     * The movie duration in minutes.
     */
    private int duration;

    /**
     * The movie release year.
     */
    private int year;

    /**
     * Default constructor required by JPA.
     * <p>
     * Hibernate uses it to create the instance when reading a record from the
     * database. Not intended for direct use.
     */
    public Movie() {
    }

    /**
     * Creates a new movie without an identifier.
     * <p>
     * The {@code id} is assigned when the movie is saved to the database.
     *
     * @param title the movie title
     * @param genre the genre (for example, "Action")
     * @param filmRating the age rating
     * @param duration the duration in minutes
     * @param year the release year
     */
    public Movie(String title, String genre, String filmRating, int duration, int year) {
        this.title = title;
        this.genre = genre;
        this.filmRating = filmRating;
        this.duration = duration;
        this.year = year;
    }

    /**
     * Returns the movie ID.
     *
     * @return the ID
     */
    public Long getId() {
        return id;
    }

    /**
     * Sets the movie ID.
     * <p>
     * The ID is normally generated by the database when the movie is saved, so
     * this method should not be called manually.
     *
     * @param id the new ID
     */
    public void setId(Long id) {
        this.id = id;
    }

    /**
     * Returns the movie title.
     *
     * @return the title
     */
    public String getTitle() {
        return title;
    }

    /**
     * Sets the movie title.
     *
     * @param title the new title
     */
    public void setTitle(String title) {
        this.title = title;
    }

    /**
     * Returns the movie genre.
     *
     * @return the genre
     */
    public String getGenre() {
        return genre;
    }

    /**
     * Sets the movie genre.
     *
     * @param genre the new genre
     */
    public void setGenre(String genre) {
        this.genre = genre;
    }

    /**
     * Returns the movie rating.
     *
     * @return the rating (ATP, +13, +16, +18)
     */
    public String getFilmRating() {
        return filmRating;
    }

    /**
     * Sets the movie rating.
     *
     * @param filmRating the new rating
     */
    public void setFilmRating(String filmRating) {
        this.filmRating = filmRating;
    }

    /**
     * Returns the movie duration.
     *
     * @return the duration in minutes
     */
    public int getDuration() {
        return duration;
    }

    /**
     * Sets the movie duration.
     *
     * @param duration the new duration
     */
    public void setDuration(int duration) {
        this.duration = duration;
    }

    /**
     * Returns the release year.
     *
     * @return the year of release
     */
    public int getYear() {
        return year;
    }

    /**
     * Sets the release year.
     *
     * @param year the new year
     */
    public void setYear(int year) {
        this.year = year;
    }

    /**
     * Returns a text representation of the movie, used to display it in combo
     * boxes.
     *
     * @return the title followed by the year in parentheses, for example "Dune
     * (2021)"
     *
     */
    @Override
    public String toString() {
        return title + " (" + year + ")";
    }
}
